per_step.command:
awk -F, 'BEGIN{OFS=","} NR==1{print $0} NR>1{
  if ($5 == "Cancer") { $7 = 4; $8 = 90 }
  else if ($5 == "Heart Disease") { $7 = 3; $8 = 90 }
  else if ($5 == "Diabetes") { $7 = 2; $8 = 90 }
  else if ($5 == "Hypertension") { $7 = 2; $8 = 90 }
  else if ($5 == "Arthritis") { $7 = 1; $8 = 90 }
  else if ($5 == "Asthma") { $7 = 1; $8 = 90 }
  print $0
}' /app/data/patient_data/patient_data.csv > /app/data/patient_data/patient_data_new.csv && mv /app/data/patient_data/patient_data_new.csv /app/data/patient_data/patient_data.csv
